import json,sys
import numpy as np
from scipy.optimize import minimize_scalar
sys.path.insert(0,'/app')
import model
D=json.load(open('/app/data/calibration.json'))
def obj(J):
 p=model.predict_at([r['input'] for r in D],J)
 y=np.array([r['value'] for r in D]); s=np.array([r['sigma'] for r in D])
 return np.sum(((p-y)/s)**2)
r=minimize_scalar(obj,bounds=(.8,1.2),method='bounded',options={'xatol':1e-14})
print(r, 'mse',r.fun/len(D))
for J in [.95,1,1.05,1.1]: print(J,obj(J)/len(D))
PY",workdir:"/app",yield_time_ms:10000,max_output_tokens:10000});
